<template>
  <!-- Bố cục: VaLayout chia vùng điều hướng và nội dung; sidebar là overlay nên đóng/mở không đổi kích thước view. -->
  <VaLayout
    :class="{ 'app-layout--city': isCity }"
    :top="{ fixed: true, order: 2 }"
    :left="{
      fixed: true,
      absolute: true,
      order: 1,
      overlay: !isSidebarMinimized,
    }"
    @leftOverlayClick="isSidebarMinimized = true"
    @keydown.esc="isSidebarMinimized = true"
  >
    <template #top>
      <!-- <AppNavbar :is-mobile="isMobile" /> -->
    </template>

    <template #left>
      <!-- Sidebar nằm trong vùng left absolute của VaLayout; inert ngăn focus vào menu đang thu gọn. -->
      <AppSidebar
        id="app-sidebar"
        :minimized="isSidebarMinimized"
        :animated="!isMobile"
        :mobile="isMobile"
        :inert="isSidebarMinimized"
        @close="isSidebarMinimized = true"
      />
    </template>

    <template #content>
      <AppLayoutNavigation class="p-4" />
      <main :class="isCity ? 'flex-1 min-h-0' : 'p-4 pt-0'">
        <article :class="{ 'h-full': isCity }">
          <RouterView />
        </article>
      </main>
    </template>
  </VaLayout>
</template>

<script setup>
import { onBeforeUnmount, onMounted, ref, computed } from 'vue'
import { storeToRefs } from 'pinia'
import { onBeforeRouteUpdate, useRoute } from 'vue-router'
import { useBreakpoint } from 'vuestic-ui'

import { useGlobalStore } from '../stores/global-store'

import AppLayoutNavigation from '../components/app-layout-navigation/AppLayoutNavigation.vue'
import AppSidebar from '../components/sidebar/AppSidebar.vue'

const route = useRoute()
const isCity = computed(() => ['city', 'flumeCity'].includes(route.name))

const GlobalStore = useGlobalStore()

const breakpoints = useBreakpoint()

const isMobile = ref(false)
const { isSidebarMinimized } = storeToRefs(GlobalStore)

const onResize = () => {
  if (breakpoints.mdDown) isSidebarMinimized.value = true
  isMobile.value = breakpoints.smDown
}

onMounted(() => {
  window.addEventListener('resize', onResize)
  onResize()
})

onBeforeUnmount(() => {
  window.removeEventListener('resize', onResize)
})

onBeforeRouteUpdate(() => {
  isSidebarMinimized.value = true
})
</script>

<style lang="scss" scoped>
.app-layout--city :deep(.va-layout__area--content) {
  display: flex;
  flex-direction: column;
  height: calc(100dvh - var(--va-paddings-top-px) - var(--va-paddings-bottom-px));
}

// Prevent icon jump on animation
.va-sidebar {
  width: unset !important;
  min-width: unset !important;
}
</style>
